function demoMain(idx,label){
  var pkgs=[["leftpad","MIT","allow"],["gpl-lib","GPL-3.0","review"],["pro-lib","Proprietary","deny"]];
  var p=pkgs[idx%pkgs.length];
  return "["+label+"] "+p[0]+" ("+p[1]+") => policy "+p[2];
}

